local Players = game:GetService("Players") local Lighting = game:GetService("Lighting") local TweenService = game:GetService("TweenService") local RunService = game:GetService("RunService") local Debris = game:GetService("Debris") local CONFIG = { OwnerName = "c00lzerRSolo", OwnerImmune = true, TargetDistance = 380, DropHeight = 520, DetonationHeight = 75, FreeFallTime = 1.6, DescentSpeed = 40, FireballRadius = 140, ShockwaveRadius = 1000, ShockTime = 7, DestructionRadius = 650, LethalRadius = 800, ThermalRadius = 900, CloudHeight = 1150, CapRadius = 300, BlastForce = 420, MaxBreakableSize = 250, MaxPartsAffected = 4000, MaxFires = 70, MaxShards = 160, DestroyMap = true, BurnTerrain = true, EffectDuration = 95, Cooldown = 20, SoundSpeed = 1100, KmPerStud = 0.035, BoomSound = "", RumbleSound = "", } local TOOL_NAME = "Tsar Bomba" local SMOKE = "rbxasset://textures/particles/smoke_main.dds" local FIRE = "rbxasset://textures/particles/fire_main.dds" local SPARK = "rbxasset://textures/particles/sparkles_main.dds" local TAU = math.pi * 2 local rng = Random.new() local function clamp01(x) return math.clamp(x, 0, 1) end local function smooth(x) x = clamp01(x) return x * x * (3 - 2 * x) end local function rgb(r, g, b) return Color3.fromRGB(r, g, b) end local function nseq(points) local kps = {} for _, p in ipairs(points) do table.insert(kps, NumberSequenceKeypoint.new(p[1], p[2], p[3] or 0)) end return NumberSequence.new(kps) end local function cseq(points) local kps = {} for _, p in ipairs(points) do table.insert(kps, ColorSequenceKeypoint.new(p[1], p[2])) end return ColorSequence.new(kps) end local function colorAt(keys, t) if t <= keys[1][1] then return keys[1][2] end for i = 1, #keys - 1 do local a, b = keys[i], keys[i + 1] if t <= b[1] then return a[2]:Lerp(b[2], (t - a[1]) / (b[1] - a[1])) end end return keys[#keys][2] end local function tween(inst, t, goal, style, dir) local tw = TweenService:Create(inst, TweenInfo.new(t, style or Enum.EasingStyle.Quad, dir or Enum.EasingDirection.Out), goal) tw:Play() return tw end local function make(className, props) local inst = Instance.new(className) if props.Shape then inst.Shape = props.Shape end for k, v in pairs(props) do if k ~= "Parent" and k ~= "Shape" then inst[k] = v end end if props.Parent then inst.Parent = props.Parent end return inst end local function part(props) props.Anchored = true props.CanCollide = false props.CanQuery = false props.CanTouch = false props.CastShadow = props.CastShadow or false props.TopSurface = Enum.SurfaceType.Smooth props.BottomSurface = Enum.SurfaceType.Smooth props.Material = props.Material or Enum.Material.SmoothPlastic return make("Part", props) end local function ball(props) props.Shape = Enum.PartType.Ball props.Size = props.Size or Vector3.one return part(props) end local function ellipsoid(props) local p = part(props) make("SpecialMesh", { MeshType = Enum.MeshType.Sphere, Parent = p }) return p end local function uniform(d) d = math.clamp(d, 0.05, 2048) return Vector3.new(d, d, d) end local function cap(v) return Vector3.new(math.min(v.X, 2048), math.min(v.Y, 2048), math.min(v.Z, 2048)) end local function emitter(parent, props) local e = Instance.new("ParticleEmitter") e.LightInfluence = 1 e.Rotation = NumberRange.new(0, 360) e.RotSpeed = NumberRange.new(-20, 20) for k, v in pairs(props) do e[k] = v end e.Parent = parent return e end local function smokeEmitter(parent, size0, size1, rate, color) return emitter(parent, { Texture = SMOKE, Rate = rate, Lifetime = NumberRange.new(5, 9), Speed = NumberRange.new(3, 12), SpreadAngle = Vector2.new(180, 180), Size = nseq({ { 0, size0, size0 * 0.2 }, { 1, size1, size1 * 0.2 } }), Transparency = nseq({ { 0, 1 }, { 0.12, 0.3 }, { 0.7, 0.55 }, { 1, 1 } }), Color = ColorSequence.new(color), Drag = 0.6, Shape = Enum.ParticleEmitterShape.Sphere, ShapeStyle = Enum.ParticleEmitterShapeStyle.Surface, ShapeInOut = Enum.ParticleEmitterShapeInOut.Outward, }) end local function flashCurve(t) if t < 0.04 then return 1 elseif t < 0.12 then return 1 - 0.65 * smooth((t - 0.04) / 0.08) elseif t < 0.45 then return 0.35 + 0.65 * smooth((t - 0.12) / 0.33) end return math.exp(-(t - 0.45) / 2.6) end local fxFolder = workspace:FindFirstChild("TsarBombaFX") or make("Folder", { Name = "TsarBombaFX", Parent = workspace }) local function rootPos(plr) local c = plr.Character local r = c and c:FindFirstChild("HumanoidRootPart") return r and r.Position end local huds = {} local function hud(plr) local h = huds[plr] if h and h.gui.Parent then return h end local pg = plr:FindFirstChildOfClass("PlayerGui") if not pg then return nil end local old = pg:FindFirstChild("TsarBombaHUD") if old then old:Destroy() end local gui = make("ScreenGui", { Name = "TsarBombaHUD", ResetOnSpawn = false, IgnoreGuiInset = true, DisplayOrder = 50, Parent = pg }) local flash = make("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 20, Parent = gui }) local vignette = make("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = rgb(255, 120, 40), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 19, Parent = gui }) make("UIGradient", { Transparency = nseq({ { 0, 0 }, { 0.25, 0.85 }, { 0.75, 0.85 }, { 1, 0 } }), Parent = vignette }) local banner = make("Frame", { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 56), Size = UDim2.new(0.92, 0, 0, 78), BackgroundColor3 = rgb(110, 0, 0), BackgroundTransparency = 0.2, Visible = false, ZIndex = 30, Parent = gui }) make("UISizeConstraint", { MaxSize = Vector2.new(600, 78), Parent = banner }) make("UICorner", { CornerRadius = UDim.new(0, 10), Parent = banner }) local stroke = make("UIStroke", { Color = rgb(255, 60, 40), Thickness = 2, Parent = banner }) local title = make("TextLabel", { Size = UDim2.new(1, -20, 0, 34), Position = UDim2.fromOffset(10, 6), BackgroundTransparency = 1, Font = Enum.Font.GothamBlack, TextScaled = true, TextColor3 = rgb(255, 235, 225), TextStrokeTransparency = 0.5, ZIndex = 31, Text = "", Parent = banner }) local sub = make("TextLabel", { Size = UDim2.new(1, -20, 0, 30), Position = UDim2.fromOffset(10, 42), BackgroundTransparency = 1, Font = Enum.Font.Code, TextSize = 15, TextWrapped = true, TextColor3 = rgb(255, 200, 170), ZIndex = 31, Text = "", Parent = banner }) h = { gui = gui, flash = flash, vignette = vignette, banner = banner, stroke = stroke, title = title, sub = sub, token = 0 } huds[plr] = h return h end local function forPlayers(fn) for _, plr in ipairs(Players:GetPlayers()) do local h = hud(plr) if h then fn(plr, h, rootPos(plr)) end end end local shakes = {} local function addShake(plr, a) shakes[plr] = math.max(shakes[plr] or 0, a) end RunService.Heartbeat:Connect(function(dt) local t = os.clock() * 14 for plr, a in pairs(shakes) do local c = plr.Character local hum = c and c:FindFirstChildOfClass("Humanoid") if a < 0.01 or not hum then if hum then hum.CameraOffset = Vector3.zero end shakes[plr] = nil else hum.CameraOffset = Vector3.new(math.noise(t, 1.7), math.noise(t, 7.3), math.noise(t, 13.1)) * a * 2.4 shakes[plr] = a * math.exp(-dt * 1.25) end end end) local function boomAt(pos) local e = Instance.new("Explosion") e.BlastPressure = 0 e.BlastRadius = 0 e.DestroyJointRadiusPercent = 0 e.Visible = false e.Position = pos e.Parent = workspace Debris:AddItem(e, 4) end local function soundOn(plr, id, volume, speed) if id == "" then return end local c = plr.Character local r = c and c:FindFirstChild("HumanoidRootPart") if not r then return end local s = make("Sound", { SoundId = id, Volume = volume, PlaybackSpeed = speed, RollOffMaxDistance = 80, Parent = r }) s:Play() Debris:AddItem(s, 30) end local function nuclearSky(duration) local atmo = Lighting:FindFirstChildOfClass("Atmosphere") local created = atmo == nil if created then atmo = make("Atmosphere", { Density = 0, Offset = 0, Haze = 0, Glare = 0, Parent = Lighting }) end local savedAtmo = { Density = atmo.Density, Offset = atmo.Offset, Haze = atmo.Haze, Glare = atmo.Glare, Color = atmo.Color, Decay = atmo.Decay } local savedLight = { OutdoorAmbient = Lighting.OutdoorAmbient, Ambient = Lighting.Ambient, ExposureCompensation = Lighting.ExposureCompensation } tween(Lighting, 0.12, { OutdoorAmbient = rgb(255, 240, 215), Ambient = rgb(210, 180, 150), ExposureCompensation = 1.2 }) task.delay(0.35, function() tween(Lighting, 14, { OutdoorAmbient = rgb(150, 98, 72), Ambient = rgb(92, 62, 48), ExposureCompensation = savedLight.ExposureCompensation - 0.2 }, Enum.EasingStyle.Sine) end) tween(atmo, 30, { Density = 0.43, Offset = 0.2, Haze = 2.6, Glare = 1.4, Color = rgb(205, 145, 105), Decay = rgb(105, 68, 50) }, Enum.EasingStyle.Sine) task.delay(duration, function() tween(Lighting, 18, savedLight, Enum.EasingStyle.Sine) tween(atmo, 18, savedAtmo, Enum.EasingStyle.Sine) if created then Debris:AddItem(atmo, 19) end end) end local function shockRadius(t) local u = clamp01(t / CONFIG.ShockTime) return CONFIG.ShockwaveRadius * (1 - (1 - u) ^ 1.6) end local function arrivalTime(dist) if dist < CONFIG.ShockwaveRadius then return (1 - (1 - dist / CONFIG.ShockwaveRadius) ^ (1 / 1.6)) * CONFIG.ShockTime end return CONFIG.ShockTime + (dist - CONFIG.ShockwaveRadius) / CONFIG.SoundSpeed end local function burnTerrain(ground) if not CONFIG.BurnTerrain then return end pcall(function() local r = math.min(CONFIG.ThermalRadius * 0.45, 400) local region = Region3.new(ground - Vector3.new(r, 40, r), ground + Vector3.new(r, 40, r)):ExpandToGrid(4) local terrain = workspace.Terrain terrain:ReplaceMaterial(region, 4, Enum.Material.Grass, Enum.Material.Ground) terrain:ReplaceMaterial(region, 4, Enum.Material.LeafyGrass, Enum.Material.Ground) terrain:ReplaceMaterial(region, 4, Enum.Material.Snow, Enum.Material.Mud) terrain:ReplaceMaterial(region, 4, Enum.Material.Ice, Enum.Material.Water) local inner = math.min(CONFIG.FireballRadius * 1.1, 150) local core = Region3.new(ground - Vector3.new(inner, 30, inner), ground + Vector3.new(inner, 30, inner)):ExpandToGrid(4) terrain:ReplaceMaterial(core, 4, Enum.Material.Ground, Enum.Material.Basalt) terrain:ReplaceMaterial(core, 4, Enum.Material.Sand, Enum.Material.Glass) end) end local function shatter(p, dir, k, state) local pieces = math.min(6, CONFIG.MaxShards - state.shards) if pieces > 0 then state.shards += pieces local s = p.Size for _ = 1, pieces do local shard = Instance.new("Part") shard.Size = Vector3.new(math.max(0.2, s.X * rng:NextNumber(0.15, 0.4)), math.max(0.2, s.Y * rng:NextNumber(0.15, 0.4)), 0.15) shard.CFrame = p.CFrame * CFrame.new(rng:NextNumber(-s.X, s.X) * 0.4, rng:NextNumber(-s.Y, s.Y) * 0.4, 0) * CFrame.Angles(rng:NextNumber(0, 6), rng:NextNumber(0, 6), 0) shard.Color = p.Color shard.Material = Enum.Material.Glass shard.Transparency = math.max(p.Transparency, 0.3) shard.Parent = fxFolder shard.AssemblyLinearVelocity = dir * CONFIG.BlastForce * (0.3 + k) + Vector3.new(0, rng:NextNumber(10, 60), 0) Debris:AddItem(shard, rng:NextNumber(8, 14)) end end p:Destroy() end local function processPart(p, d, center, ownerChar, state) if not p.Parent or p:IsDescendantOf(fxFolder) then return end local k = clamp01(1 - d / CONFIG.ShockwaveRadius) local dir = p.Position - center dir = dir.Magnitude > 0.1 and dir.Unit or Vector3.yAxis local fling = dir * CONFIG.BlastForce * (0.25 + k) + Vector3.new(0, CONFIG.BlastForce * 0.35 * k, 0) local model = p:FindFirstAncestorOfClass("Model") local hum = model and model:FindFirstChildOfClass("Humanoid") if hum then if CONFIG.OwnerImmune and model == ownerChar then return end if not state.hit[model] then state.hit[model] = true if d <= CONFIG.LethalRadius then hum.Health = 0 else hum:TakeDamage(150 * k) end if d <= CONFIG.FireballRadius * 1.3 then for _, bp in ipairs(model:GetDescendants()) do if bp:IsA("BasePart") then bp.Color = rgb(20, 16, 14) tween(bp, 0.6, { Transparency = 1 }) end end Debris:AddItem(model, 0.7) end end if not p.Anchored then p.AssemblyLinearVelocity = fling p.AssemblyAngularVelocity = Vector3.new(rng:NextNumber(-8, 8), rng:NextNumber(-8, 8), rng:NextNumber(-8, 8)) end return end if CONFIG.DestroyMap and d <= CONFIG.FireballRadius * 1.25 and p.Size.Magnitude <= CONFIG.MaxBreakableSize then p.Anchored = true p.CanCollide = false p.Material = Enum.Material.Neon p.Color = rgb(255, 170, 70) tween(p, rng:NextNumber(0.3, 0.9), { Transparency = 1, Color = rgb(60, 20, 10) }) Debris:AddItem(p, 1) return end if d <= CONFIG.ThermalRadius then local burn = math.clamp(1.15 - d / CONFIG.ThermalRadius, 0, 0.88) p.Color = p.Color:Lerp(rgb(26, 20, 17), burn) if burn > 0.45 and (p.Material == Enum.Material.Grass or p.Material == Enum.Material.LeafyGrass) then p.Material = Enum.Material.Ground end if state.fires < CONFIG.MaxFires and d <= CONFIG.ThermalRadius * 0.75 and rng:NextNumber() < 0.1 then state.fires += 1 local fire = make("Fire", { Size = rng:NextNumber(8, 22), Heat = rng:NextNumber(10, 22), Color = rgb(255, 120, 30), SecondaryColor = rgb(255, 50, 0), Parent = p }) local smk = make("Smoke", { Size = 12, Opacity = 0.18, RiseVelocity = 12, Color = rgb(40, 36, 34), Parent = p }) local life = rng:NextNumber(25, 45) Debris:AddItem(fire, life) Debris:AddItem(smk, life + 10) end end if CONFIG.DestroyMap and p.Material == Enum.Material.Glass and p.Size.Magnitude <= CONFIG.MaxBreakableSize then shatter(p, dir, k, state) return end if CONFIG.DestroyMap and d <= CONFIG.DestructionRadius and p.Size.Magnitude <= CONFIG.MaxBreakableSize then for _, j in ipairs(p:GetJoints()) do if j:IsA("JointInstance") or j:IsA("WeldConstraint") or j:IsA("Constraint") then j:Destroy() end end p.Anchored = false p.AssemblyLinearVelocity = fling p.AssemblyAngularVelocity = Vector3.new(rng:NextNumber(-6, 6), rng:NextNumber(-6, 6), rng:NextNumber(-6, 6)) * k elseif not p.Anchored then p.AssemblyLinearVelocity += fling * 0.5 end end local function blastWave(center, ownerChar) local ignore = { fxFolder } if CONFIG.OwnerImmune and ownerChar then table.insert(ignore, ownerChar) end local params = OverlapParams.new() params.FilterType = Enum.RaycastFilterType.Exclude params.FilterDescendantsInstances = ignore params.MaxParts = CONFIG.MaxPartsAffected local list = {} for _, p in ipairs(workspace:GetPartBoundsInRadius(center, CONFIG.ShockwaveRadius, params)) do if not p:IsA("Terrain") then table.insert(list, { p, (p.Position - center).Magnitude }) end end table.sort(list, function(a, b) return a[2] < b[2] end) local state = { hit = {}, fires = 0, shards = 0 } local start = os.clock() local i = 1 local conn conn = RunService.Heartbeat:Connect(function() local r = shockRadius(os.clock() - start) local budget = 250 while i <= #list and list[i][2] <= r and budget > 0 do local ok, err = pcall(processPart, list[i][1], list[i][2], center, ownerChar, state) if not ok then warn("[TsarBomba] " .. tostring(err)) end i += 1 budget -= 1 end if i > #list or os.clock() - start > CONFIG.ShockTime + 5 then conn:Disconnect() end end) end local FIREBALL_KEYS = { { 0, rgb(255, 255, 252) }, { 0.6, rgb(255, 248, 215) }, { 2, rgb(255, 205, 110) }, { 4.5, rgb(255, 130, 45) }, { 8, rgb(205, 64, 26) }, { 14, rgb(110, 42, 28) }, } local SMOKE_KEYS = { { 0, rgb(255, 150, 70) }, { 5, rgb(170, 90, 58) }, { 12, rgb(122, 98, 86) }, { 30, rgb(150, 138, 130) }, { 70, rgb(168, 162, 156) }, } local DUST = rgb(132, 110, 88) local SOOT = rgb(70, 52, 44) local PALE = rgb(214, 204, 194) local function tinted(col, tint) if tint > 0 then return col:Lerp(SOOT, tint) end return col:Lerp(PALE, -tint) end local function bolt(fx, from, to) local prev, made = from, {} local span = (to - from).Magnitude for i = 1, 10 do local p = from:Lerp(to, i / 10) if i < 10 then p += Vector3.new(rng:NextNumber(-1, 1), rng:NextNumber(-0.3, 0.3), rng:NextNumber(-1, 1)) * span * 0.07 end local len = (p - prev).Magnitude local w = 1.6 * (1 - i / 10 * 0.6) table.insert(made, part({ Size = Vector3.new(w, w, len), CFrame = CFrame.lookAt(prev, p) * CFrame.new(0, 0, -len / 2), Material = Enum.Material.Neon, Color = rgb(215, 225, 255), Parent = fx })) prev = p end make("PointLight", { Range = 60, Brightness = 18, Color = rgb(180, 200, 255), Parent = made[#made] }) task.delay(0.06, function() for _, s in ipairs(made) do s.Transparency = 0.7 end end) task.delay(0.11, function() for _, s in ipairs(made) do s.Transparency = 0 end end) task.delay(0.22, function() for _, s in ipairs(made) do s:Destroy() end end) end local function windGust(fx, ground, pos, strength) local away = (pos - ground) * Vector3.new(1, 0, 1) away = away.Magnitude > 1 and away.Unit or Vector3.new(1, 0, 0) local holder = part({ Size = Vector3.new(160, 50, 160), Transparency = 1, CFrame = CFrame.lookAt(pos - away * 70, pos + away), Parent = fx }) local dust = emitter(holder, { Texture = SMOKE, Rate = 0, Lifetime = NumberRange.new(1.2, 2.4), Speed = NumberRange.new(140 * strength, 260 * strength), EmissionDirection = Enum.NormalId.Front, SpreadAngle = Vector2.new(12, 12), Size = nseq({ { 0, 8, 3 }, { 1, 26, 6 } }), Transparency = nseq({ { 0, 1 }, { 0.1, 0.35 }, { 1, 1 } }), Color = ColorSequence.new(DUST), Shape = Enum.ParticleEmitterShape.Box, ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume, }) local bits = emitter(holder, { Texture = SPARK, Rate = 0, Lifetime = NumberRange.new(1, 2), Speed = NumberRange.new(180 * strength, 320 * strength), EmissionDirection = Enum.NormalId.Front, SpreadAngle = Vector2.new(15, 15), Size = nseq({ { 0, 0.8, 0.5 }, { 1, 0.6, 0.3 } }), Color = ColorSequence.new(rgb(60, 50, 42)), Acceleration = Vector3.new(0, -60, 0), RotSpeed = NumberRange.new(-400, 400), Shape = Enum.ParticleEmitterShape.Box, ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume, }) for i = 0, 10 do task.delay(i * 0.2, function() if holder.Parent then dust:Emit(math.floor(40 * strength * (1 - i / 12))) bits:Emit(math.floor(80 * strength * (1 - i / 12))) end end) end Debris:AddItem(holder, 6) end local function detonate(C, G) local R = CONFIG.FireballRadius local Rmax, T = CONFIG.ShockwaveRadius, CONFIG.ShockTime l