(t - 1) / 3) do local parts, cfs = {}, {} for i, s in ipairs(stem) do local u = s.u local y = groundY + capBottom - (1 - u) * capBottom * reach local r = stemR * (1 + 1.7 * (1 - u) ^ 5) * (1 + 0.55 * u ^ 3) * s.scale local wob = Vector3.new(math.sin(t * 0.25 + s.wob), 0, math.cos(t * 0.21 + s.wob)) * stemR * 0.18 * u s.part.Size = uniform(math.max(r * 2, 0.1)) s.part.Color = tinted(DUST:Lerp(smokeCol, u ^ 0.7), s.tint):Lerp(hot, clamp01(math.exp(-t / 6) * u)) local st = 1 - 0.82 * stemAppear s.part.Transparency = st + (1 - st) * fadeOut parts[i] = s.part cfs[i] = CFrame.new(Vector3.new(C.X, y, C.Z) + wob) end workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged) end do local surge = 1 - math.exp(-math.max(t - 0.6, 0) / 11) local parts, cfs = {}, {} for i, b in ipairs(base) do local d2 = (RC * 0.35 + RC * 1.5 * surge) * b.reach local size = RC * (0.25 + 0.4 * surge) * b.scale b.part.Size = uniform(size) b.part.Color = tinted(DUST, b.tint) local bt = 1 - 0.7 * smooth((t - 0.6) / 2) b.part.Transparency = bt + (1 - bt) * math.max(fadeOut, smooth((t - duration * 0.6) / (duration * 0.4))) parts[i] = b.part cfs[i] = CFrame.new(G + Vector3.new(math.cos(b.theta) * d2, size * 0.28, math.sin(b.theta) * d2)) end workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged) end for idx, c in ipairs(collars) do local life = (t - (3 + idx * 0.8)) / 12 if life > 0 and life < 1 then local d = capR * (1.25 + 1.5 * smooth(life)) c.part.Size = cap(Vector3.new(d, d * 0.05, d)) c.part.CFrame = CFrame.new(Vector3.new(C.X, groundY + capH * c.frac, C.Z)) c.part.Transparency = 1 - 0.62 * math.sin(math.pi * life) else c.part.Transparency = 1 end end local plife = (t - 5) / 24 if plife > 0 and plife < 1 then local d = capR * (2.3 + 0.6 * plife) pileus.Size = cap(Vector3.new(d, capR * 0.12, d)) pileus.CFrame = CFrame.new(capC + Vector3.new(0, tubeR * 1.15 + capR * 0.08, 0)) pileus.Transparency = 1 - 0.55 * math.sin(math.pi * plife) else pileus.Transparency = 1 end if t - lastHud > 0.1 then lastHud = t local fireballKm = (core.Parent and core.Size.X or 0) * CONFIG.KmPerStud for _, v in pairs(viewers) do if v.token == v.h.token then if not v.arrived then v.h.sub.Text = string.format("%.1f km from ground zero · fireball Ø %.1f km · blast wave in %.1f s", v.dist * CONFIG.KmPerStud, fireballKm, math.max(v.arrival - t, 0)) else v.h.sub.Text = string.format("blast wave passed · cloud top %.0f km and rising", capH * CONFIG.KmPerStud * 1.35) end v.h.stroke.Color = (t * 3) % 1 < 0.5 and rgb(255, 140, 40) or rgb(120, 40, 0) if v.arrived and t > v.arrival + 10 then v.h.banner.Visible = false end end end end end) task.delay(duration, function() for _, d in ipairs(fx:GetDescendants()) do if d:IsA("ParticleEmitter") then d.Enabled = false end end end) task.delay(duration + 15, function() fx:Destroy() cc:Destroy() bloom:Destroy() blur:Destroy() end) end local function buildBomb() local model = Instance.new("Model") model.Name = "TsarBomba_AN602" local metal, dark = rgb(88, 94, 84), rgb(52, 56, 50) local pieces = {} local function add(p, offset) p.CFrame = offset p.Parent = model table.insert(pieces, { p, offset }) return p end local body = add(part({ Name = "Body", Shape = Enum.PartType.Cylinder, Size = Vector3.new(20, 7.6, 7.6), Color = metal, Material = Enum.Material.Metal, CastShadow = true }), CFrame.new()) add(ellipsoid({ Name = "Nose", Size = Vector3.new(11, 7.6, 7.6), Color = metal, Material = Enum.Material.Metal, CastShadow = true }), CFrame.new(10, 0, 0)) add(part({ Name = "Fuze", Shape = Enum.PartType.Cylinder, Size = Vector3.new(1.2, 1.4, 1.4), Color = dark, Material = Enum.Material.Metal }), CFrame.new(15.3, 0, 0)) add(part({ Name = "TailCone", Shape = Enum.PartType.Cylinder, Size = Vector3.new(5, 6.2, 6.2), Color = metal, Material = Enum.Material.Metal, CastShadow = true }), CFrame.new(-12.5, 0, 0)) add(part({ Name = "TailCap", Shape = Enum.PartType.Cylinder, Size = Vector3.new(3, 4.4, 4.4), Color = dark, Material = Enum.Material.Metal }), CFrame.new(-16.5, 0, 0)) for _, x in ipairs({ -8.5, -3, 3.5, 8.6 }) do add(part({ Name = "Band", Shape = Enum.PartType.Cylinder, Size = Vector3.new(0.45, 7.85, 7.85), Color = dark, Material = Enum.Material.DiamondPlate }), CFrame.new(x, 0, 0)) end for _, x in ipairs({ -4, 4 }) do add(part({ Name = "Lug", Size = Vector3.new(0.8, 0.9, 1.6), Color = dark, Material = Enum.Material.Metal }), CFrame.new(x, 4.1, 0)) end for i = 0, 3 do local a = i * math.pi / 2 add(part({ Name = "Fin", Size = Vector3.new(7.5, 5.2, 0.35), Color = metal, Material = Enum.Material.Metal, CastShadow = true }), CFrame.Angles(a, 0, 0) * CFrame.new(-14.5, 5.6, 0)) add(part({ Name = "FinTip", Size = Vector3.new(5, 0.35, 2.4), Color = dark, Material = Enum.Material.Metal }), CFrame.Angles(a, 0, 0) * CFrame.new(-15.5, 8.2, 0)) end add(part({ Name = "Stripe", Shape = Enum.PartType.Cylinder, Size = Vector3.new(0.8, 7.7, 7.7), Color = rgb(150, 25, 20) }), CFrame.new(6, 0, 0)) local beacon = add(part({ Name = "Beacon", Shape = Enum.PartType.Ball, Size = Vector3.new(1.1, 1.1, 1.1), Color = rgb(255, 30, 30), Material = Enum.Material.Neon }), CFrame.new(-18.3, 0, 0)) local beaconLight = make("PointLight", { Color = rgb(255, 40, 40), Range = 22, Brightness = 6, Parent = beacon }) local pack = add(part({ Name = "ChutePack", Shape = Enum.PartType.Cylinder, Size = Vector3.new(2.4, 3.6, 3.6), Color = rgb(70, 80, 60), Material = Enum.Material.Fabric }), CFrame.new(-19.2, 0, 0)) local riser = make("Attachment", { Name = "Riser", Position = Vector3.new(-1, 0, 0), Parent = pack }) local canopy = ellipsoid({ Name = "Canopy", Size = Vector3.new(2, 2, 2), Color = rgb(235, 120, 40), Material = Enum.Material.Fabric, Transparency = 1, CastShadow = true, Parent = model }) local canopyInner = ellipsoid({ Name = "CanopyInner", Size = Vector3.new(2, 2, 2), Color = rgb(240, 236, 225), Material = Enum.Material.Fabric, Transparency = 1, Parent = model }) local vent = part({ Name = "Vent", Shape = Enum.PartType.Cylinder, Size = Vector3.new(0.6, 6, 6), Color = rgb(40, 40, 40), Transparency = 1, Parent = model }) local rim, beams = {}, {} for i = 1, 16 do local att = make("Attachment", { Name = "Rim" .. i, Parent = canopy }) rim[i] = { att, (i - 1) / 16 * TAU } beams[i] = make("Beam", { Attachment0 = riser, Attachment1 = att, Width0 = 0.18, Width1 = 0.18, FaceCamera = true, Color = ColorSequence.new(rgb(220, 215, 200)), Segments = 1, Transparency = NumberSequence.new(0.1), Enabled = false, Parent = canopy }) end local bb = make("BillboardGui", { Name = "Telemetry", Adornee = body, Size = UDim2.fromOffset(300, 104), StudsOffset = Vector3.new(0, 20, 0), AlwaysOnTop = true, MaxDistance = 4000, LightInfluence = 0, Parent = body }) local frame = make("Frame", { Size = UDim2.fromScale(1, 1), BackgroundColor3 = rgb(15, 5, 5), BackgroundTransparency = 0.25, BorderSizePixel = 0, Parent = bb }) make("UICorner", { CornerRadius = UDim.new(0, 8), Parent = frame }) make("UIStroke", { Color = rgb(255, 50, 40), Thickness = 2, Parent = frame }) make("TextLabel", { Size = UDim2.new(1, 0, 0, 30), Position = UDim2.fromOffset(0, 4), BackgroundTransparency = 1, Text = "☢  TSAR BOMBA  ☢", Font = Enum.Font.GothamBlack, TextSize = 24, TextColor3 = rgb(255, 70, 55), TextStrokeTransparency = 0.4, Parent = frame }) make("TextLabel", { Size = UDim2.new(1, 0, 0, 18), Position = UDim2.fromOffset(0, 34), BackgroundTransparency = 1, Text = "AN602 · RDS-220 · 50 MEGATONS TNT", Font = Enum.Font.GothamBold, TextSize = 14, TextColor3 = rgb(255, 210, 190), Parent = frame }) local status = make("TextLabel", { Size = UDim2.new(1, 0, 0, 18), Position = UDim2.fromOffset(0, 56), BackgroundTransparency = 1, Text = "", Font = Enum.Font.Code, TextSize = 15, TextColor3 = Color3.new(1, 1, 1), Parent = frame }) local status2 = make("TextLabel", { Size = UDim2.new(1, 0, 0, 18), Position = UDim2.fromOffset(0, 78), BackgroundTransparency = 1, Text = "", Font = Enum.Font.Code, TextSize = 15, TextColor3 = rgb(255, 190, 90), Parent = frame }) return { model = model, pieces = pieces, beacon = beacon, beaconLight = beaconLight, canopy = canopy, canopyInner = canopyInner, vent = vent, canopyFull = Vector3.new(74, 24, 74), rim = rim, beams = beams, status = status, status2 = status2 } end local function placeBomb(b, pos, t, deploy) local sway = math.rad(7) * deploy local swing = CFrame.Angles(math.sin(t * 1.25) * sway, 0, math.cos(t * 0.9) * sway * 0.7) local yaw = CFrame.Angles(0, t * 0.35, 0) local frame = CFrame.new(pos) * swing * yaw * CFrame.Angles(0, 0, -math.pi / 2) local parts, cfs = {}, {} for i, piece in ipairs(b.pieces) do parts[i] = piece[1] cfs[i] = frame * piece[2] end workspace:BulkMoveTo(parts, cfs, Enum.BulkMoveMode.FireCFrameChanged) if deploy > 0 then local open = smooth(deploy) local full = b.canopyFull local breathe = 1 + math.sin(t * 2.3) * 0.03 * open local size = Vector3.new(full.X * (0.08 + 0.92 * open) * breathe, full.Y * (2.2 - 1.2 * open), full.Z * (0.08 + 0.92 * open) * breathe) local canopyCF = CFrame.new(pos) * swing * yaw * CFrame.new(0, 19 + 30 + 52 * deploy, 0) b.canopy.Size = size b.canopy.CFrame = canopyCF b.canopyInner.Size = Vector3.new(size.X * 0.93, size.Y * 0.8, size.Z * 0.93) b.canopyInner.CFrame = canopyCF * CFrame.new(0, -size.Y * 0.14, 0) b.vent.Size = Vector3.new(0.6, size.X * 0.09, size.X * 0.09) b.vent.CFrame = canopyCF * CFrame.new(0, size.Y * 0.5 - 0.1, 0) * CFrame.Angles(0, 0, math.pi / 2) for _, r in ipairs(b.rim) do r[1].Position = Vector3.new(math.cos(r[2]) * size.X * 0.47, -size.Y * 0.12, math.sin(r[2]) * size.Z * 0.47) end end end local function groundBelow(pos, ignore) local params = RaycastParams.new() params.FilterType = Enum.RaycastFilterType.Exclude params.FilterDescendantsInstances = ignore local hit = workspace:Raycast(pos + Vector3.new(0, 400, 0), Vector3.new(0, -4000, 0), params) return hit and hit.Position or Vector3.new(pos.X, pos.Y - 3, pos.Z) end local function groundZeroMarker(ground) local holder = part({ Name = "GroundZero", Size = Vector3.one, Transparency = 1, CFrame = CFrame.new(ground + Vector3.new(0, 1, 0)), Parent = fxFolder }) local ring = part({ Name = "GZRing", Shape = Enum.PartType.Cylinder, Size = Vector3.new(0.3, 60, 60), CFrame = CFrame.new(ground + Vector3.new(0, 0.3, 0)) * CFrame.Angles(0, 0, math.pi / 2), Color = rgb(255, 30, 20), Material = Enum.Material.Neon, Transparency = 0.55, Parent = fxFolder }) TweenService:Create(ring, TweenInfo.new(0.8, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Size = Vector3.new(0.3, 90, 90), Transparency = 0.85 }):Play() local bb = make("BillboardGui", { Size = UDim2.fromOffset(200, 50), StudsOffset = Vector3.new(0, 12, 0), AlwaysOnTop = true, LightInfluence = 0, Parent = holder }) make("TextLabel", { Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Text = "✛ GROUND ZERO ✛", Font = Enum.Font.GothamBlack, TextSize = 22, TextColor3 = rgb(255, 60, 40), TextStrokeTransparency = 0.3, Parent = bb }) return { holder, ring } end local busy = false local lastUse = -math.huge local function dropBomb(player, rootCF) busy = true local char = player.Character local look = rootCF.LookVector * Vector3.new(1, 0, 1) look = look.Magnitude > 0.01 and look.Unit or Vector3.new(0, 0, -1) local ground = groundBelow(rootCF.Position + look * CONFIG.TargetDistance, { char, fxFolder }) local releasePos = ground + Vector3.new(0, CONFIG.DropHeight, 0) local burstY = ground.Y + CONFIG.DetonationHeight local bomb = buildBomb() placeBomb(bomb, releasePos, 0, 0) bomb.model.Parent = fxFolder local marker = groundZeroMarker(ground) forPlayers(function(_, h) h.token += 1 h.banner.Visible = true h.banner.BackgroundColor3 = rgb(110, 0, 0) h.title.Text = "☢  TSAR BOMBA RELEASED  ☢" h.sub.Text = "AN602 · 50 Mt · air-burst fuze armed — TAKE COVER" end) local pos, vel = releasePos, 0 local t0 = os.clock() local deployAt local lastText = 0 while true do local dt = RunService.Heartbeat:Wait() local t = os.clock() - t0 if not deployAt and t >= CONFIG.FreeFallTime then deployAt = t bomb.canopy.Transparency = 0 bomb.canopyInner.Transparency = 0 bomb.vent.Transparency = 0 for _, beam in ipairs(bomb.beams) do beam.Enabled = true end end if deployAt then vel += (CONFIG.DescentSpeed - vel) * math.min(1, dt * 1.6) else vel += workspace.Gravity * 0.55 * dt end pos -= Vector3.new(0, vel * dt, 0) placeBomb(bomb, pos, t, deployAt and clamp01((t - deployAt) / 1.3) or 0) local on = (t * 2.5) % 1 < 0.5 bomb.beacon.Color = on and rgb(255, 30, 30) or rgb(70, 10, 10) bomb.beaconLight.Enabled = on if t - lastText > 0.1 then lastText = t local above = pos.Y - ground.Y local altKm = 4.0 + 6.5 * clamp01((above - CONFIG.DetonationHeight) / (CONFIG.DropHeight - CONFIG.DetonationHeight)) local eta = (pos.Y - burstY) / math.max(vel, 1) bomb.status.Text = string.format("ALT %5.2f km   VEL %3d m/s", altKm, math.floor(vel * 2.1)) bomb.status2.Text = deployAt and string.format("CHUTE OPEN · BURST T-%04.1fs", math.max(eta, 0)) or "FREE FALL · CHUTE ARMING" local blink = (t * 2) % 1 < 0.5 and rgb(255, 60, 40) or rgb(90, 0, 0) forPlayers(function(_, h, p) h.stroke.Color = blink if p then h.sub.Text = string.format("AN602 · 50 Mt · you are %.1f km from ground zero — TAKE COVER", ((p - ground) * Vector3.new(1, 0, 1)).Magnitude * CONFIG.KmPerStud) end end) end if pos.Y <= burstY then break end end bomb.model:Destroy() for _, m in ipairs(marker) do m:Destroy() end task.spawn(detonate, pos, ground) nuclearSky(CONFIG.EffectDuration) burnTerrain(ground) blastWave(pos, char) task.delay(CONFIG.ShockTime + 2, function() busy = false end) end local function isOwner(player) return string.lower(player.Name) == string.lower(CONFIG.OwnerName) end local function giveTool(player) local backpack = player:WaitForChild("Backpack", 10) if not backpack then return end local char = player.Character if backpack:FindFirstChild(TOOL_NAME) or (char and char:FindFirstChild(TOOL_NAME)) then return end local tool = Instance.new("Tool") tool.Name = TOOL_NAME tool.ToolTip = "AN602 · 50 Mt — equip to release" tool.RequiresHandle = false tool.CanBeDropped = false tool.Equipped:Connect(function() local c = tool.Parent local hum = c and c:FindFirstChildOfClass("Humanoid") task.defer(function() if hum and tool.Parent == c then hum:UnequipTools() end end) if not isOwner(player) or busy or os.clock() - lastUse < CONFIG.Cooldown then return end local root = c and c:FindFirstChild("HumanoidRootPart") if not root then return end lastUse = os.clock() task.spawn(function() local ok, err = pcall(dropBomb, player, root.CFrame) if not ok then warn("[TsarBomba] drop failed: " .. tostring(err)) busy = false end end) end) tool.Parent = backpack end local function onPlayer(player) if not isOwner(player) then return end player.CharacterAdded:Connect(function() task.wait(0.2) giveTool(player) end) if player.Character then task.spawn(giveTool, player) end end Players.PlayerAdded:Connect(onPlayer) for _, p in ipairs(Players:GetPlayers()) do task.spawn(onPlayer, p) end print("[TsarBomba] loaded — " .. CONFIG.OwnerName .. " has the tool")
